sys_script.script:
// ============================================================
// BR1 — FINANCIAL AGGREGATION (fixed)
// ============================================================
(function executeRule(current, previous) {

    gs.info('BR1: Starting aggregation for ' + current.getDisplayValue());

    // Returns null if field missing/empty, number otherwise
    function getNum(fieldName) {
        var raw = current.getValue(fieldName);
        if (raw === null || raw === '' || raw === undefined) return null;
        var cleaned = raw.toString().replace(/,/g, '');
        var parsed = parseFloat(cleaned);
        return isNaN(parsed) ? null : parsed;
    }

    // Only sets field if value is a real non-null number
    function setIfValid(field, value) {
        if (value !== null && isFinite(value)) {
            current.setValue(field, value);
        }
    }

    try {
        // ── 1. TOTAL SALES ──────────────────────────────────
        var readymixSale    = getNum('u_readymix_sale')    || 0;
        var concretePumping = getNum('u_concrete_pumping') || 0;
        var tmTransport     = getNum('u_tm_transportation')|| 0;
        var unbilled        = getNum('u_unbilled_revenue') || 0;
        var totalSales      = readymixSale + concretePumping + tmTransport + unbilled;

        if (totalSales > 0) {
            setIfValid('u_sales', totalSales);
            gs.info('BR1: Sales aggregated = ' + totalSales);
        } else {
            gs.warn('BR1: All sales components are zero or missing');
        }

        // ── 2. TOTAL INTEREST ────────────────────────────────
        var intTds       = getNum('u_interest_tds')          || 0;
        var intUnsecured = getNum('u_interest_unsecured')    || 0;
        var intGeneral   = getNum('u_interest_paid_general') || 0;
        var totalInterest = intTds + intUnsecured + intGeneral;

        if (totalInterest > 0) {
            setIfValid('u_interest_expense', totalInterest);
        }

        // ── 3. CURRENT ASSETS ────────────────────────────────
        var invAsset = getNum('u_inventory')          || 0;
        var ar       = getNum('u_accounts_receivable')|| 0;
        var cash     = getNum('u_cash_and_bank')      || 0;
        var loans    = getNum('u_loans_and_advances') || 0;
        var totalCA  = invAsset + ar + cash + loans;

        if (totalCA > 0) {
            setIfValid('u_current_assets', totalCA);
        }

        // ── 4. INDIRECT EXPENSES — removed unreliable subtraction ──
        // BR2 now uses addback formula (net profit + tax + interest + dep)
        // so this field is no longer needed. Keeping block for reference only.
        // If you still want it, extract indirect expenses directly via OCR
        // as a dedicated field rather than deriving it here.

        gs.info('BR1: Complete. Sales=' + totalSales + ' Assets=' + totalCA);

    } catch(e) {
        gs.error('BR1: Exception — ' + e.message);
    }

})(current, previous);
